test('renderInvoiceText with discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('Subtotal: €850.00'));
  const lineTotal = 8500;
  const lineDiscount = 850;
  const amountAfterBase = lineTotal - lineDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const totalDiscount = lineDiscount + bulkDiscount;
  const discountStr = (totalDiscount / 100).toFixed(2);
  assert.ok(text.includes(`Discount: -€${discountStr}`));
  const base = lineTotal - totalDiscount;
  const vat = Math.round(base * 0.21);
  const vatStr = (vat / 100).toFixed(2);
  assert.ok(text.includes(`VAT: +€${vatStr}`));
});

