  assert.ok(text.includes('Total: €1,580.56'));
});

test('renderInvoiceText formats large amounts with commas', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 2 },
      { sku: 'BRAND-BOOK', qty: 1 },
