test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoiceWithVoucher = {
    ...invoice,
    voucher: { code: 'TEST', amount: 1000 },
  };

  const text = renderInvoiceText(invoiceWithVoucher);
  const voucherIndex = text.indexOf('Voucher:');
  const totalIndex = text.indexOf('Total:');

  assert.ok(voucherIndex > 0);
  assert.ok(totalIndex > voucherIndex);
  assert.ok(text.includes('Voucher: -€10.00'));
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(text.includes('Due: 2025-01-29'));
});

test('renderInvoiceText does not show due date when absent', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design', qty: 1, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);

  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when there are payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const partial = {
    ...issued,
    payments: [{ amount: 5000, date: '2025-01-20' }],
  };

  const text = renderInvoiceText(partial);

  assert.ok(text.includes('Paid: €50.00'));
});

test('renderInvoiceText shows multiple payments summed', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    status: 'partially_paid',
    lines: [{ sku: 'DES-HOUR', name: 'Design', qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    payments: [
      { amount: 3000, date: '2025-01-20' },
      { amount: 2000, date: '2025-01-25' },
    ],
  };

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('Paid: €50.00'));
});

test('renderInvoiceText does not show paid line when no payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with all enhancements', () => {
  const invoice = {
    number: 'INV-2025-0001',
    customerId: 'C-001',
    customerName: 'Test Customer',
    status: 'partially_paid',
    dueDate: '2025-02-14',
    lines: [{ sku: 'DES-HOUR', name: 'Design', qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 5000 },
    payments: [{ amount: 10000, date: '2025-01-25' }],
  };

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('INV-2025-0001'));
  assert.ok(text.includes('Test Customer'));
  assert.ok(text.includes('(discount:'));
  assert.ok(text.includes('Voucher: -€50.00'));
  assert.ok(text.includes('Due: 2025-02-14'));
  assert.ok(text.includes('Paid: €100.00'));
});

test('renderInvoiceText line discount formatted correctly', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design', qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('(discount: -'));
});

