test('createInvoice preserves terms through invoice lifecycle', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  assert.equal(draft.terms, 'NET14');
  assert.equal(draft.dueDate, '2025-01-29');

  const issued = issueInvoice(draft, []).value;
  assert.equal(issued.terms, 'NET14');
  assert.equal(issued.dueDate, '2025-01-29');
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });

  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 10000);
});

test('applyVoucher reduces invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const totalsWithout = invoiceTotals(invoice);
  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 }).value;
  const totalsWith = invoiceTotals(withVoucher);

  assert.equal(totalsWith.voucher, 10000);
  assert.equal(totalsWith.total, totalsWithout.total - 10000);
});

test('applyVoucher rejects non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = applyVoucher(issued, { code: 'SAVE10', amount: 10000 });

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects duplicate voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 }).value;
  const result = applyVoucher(withVoucher, { code: 'SAVE20', amount: 20000 });

  assert.deepEqual(result, { ok: false, error: 'VOUCHER_EXISTS' });
});

