  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 850000);
  // Gold tier 5% = 42500, plus bulk 2.5% of 807500 = 20188
  assert.equal(totals.discount, 62688);
  const afterDiscount = 850000 - 62688;
  const expectedVat = 165336;
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, afterDiscount + expectedVat);
});

