test('invoiceTotals from actual createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 42500 + 95000);
  assert.equal(totals.discount, 6875);
  const afterDiscount = 137500 - 6875;
  const expectedVat = Math.round(afterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, afterDiscount + expectedVat);
});

test('addLine adds a new line to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].unitPrice, 9500);
});

