test('invoiceTotals includes voucher with discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 20000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.voucher, 20000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 20000);
});

