test('invoiceTotals with multiple lines and discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 137500);
  // DES-HOUR: 42500 * 0.10 = 4250, no bulk
  // DEV-HOUR: 95000 * 0.20 = 19000, plus 76000 * 0.025 = 1900 bulk = 20900
  assert.equal(totals.discount, 4250 + 20900);
  const afterDiscount = 137500 - 25150;
  const expectedVat = 25649;
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, afterDiscount + expectedVat);
});

