    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 20 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  // Base discount 20% = 17000, plus bulk 2.5% of 68000 = 1700
  assert.equal(totals.discount, 18700);
  const afterDiscount = 85000 - 18700;
  assert.equal(afterDiscount, 66300);
  assert.equal(totals.vat, 13923);
  assert.equal(totals.total, 85000 - 18700 + 13923);
