test('invoiceTotals with tier discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  const tierDiscount = 2125;
  assert.equal(totals.discount, tierDiscount);
  const afterDiscount = 42500 - tierDiscount;
  const expectedVat = roundCentsTest(afterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 42500 - tierDiscount + expectedVat);
});

test('invoiceTotals clamping with 100% discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-01-15',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work', qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

function roundCentsTest(x) {
  const r = Math.round(x * 1e6) / 1e6;
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

