  // DEV-HOUR: 95000 * 0.20 = 19000, plus 76000 * 0.025 = 1900 bulk = 20900
  assert.equal(totals.discount, 4250 + 20900);
  const afterDiscount = 137500 - 25150;
  const expectedVat = 23593;
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, afterDiscount + expectedVat);
});

